{
  "name": "@bangbang93/opencode-aio",
  "version": "0.1.0",
  "description": "OpenCode plugin that loads every @bangbang93/opencode plugin at once",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-aio"
  ],
  "exports": {
    ".": "./index.ts"
  },
  "files": [
    "index.ts"
  ],
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@bangbang93/opencode-bash-file-read-guard": "0.1.0",
    "@bangbang93/opencode-comment-checker": "0.1.0",
    "@bangbang93/opencode-edit-error-recovery": "0.1.0",
    "@bangbang93/opencode-write-existing-file-guard": "0.1.0",
    "@opencode/plugin": "^2.4.2"
  },
  "scripts": {
    "test": "node --test index.test.ts",
    "test:bun": "bun test",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  }
}

import { Plugin } from "@opencode/plugin"
import bashFileReadGuard from "@bangbang93/opencode-bash-file-read-guard"
import commentChecker from "@bangbang93/opencode-comment-checker"
import editErrorRecovery from "@bangbang93/opencode-edit-error-recovery"
import writeExistingFileGuard from "@bangbang93/opencode-write-existing-file-guard"

const PLUGINS = [commentChecker, editErrorRecovery, bashFileReadGuard, writeExistingFileGuard]

export default Plugin.define({
  id: "opencode-aio",
  async setup(ctx) {
    for (const plugin of PLUGINS) await plugin.setup(ctx)
  },
})
